     1→// packages/core/src/account/ops/crud.ts
     2→
     3→import { nanoid } from "nanoid";
     4→import { readAccounts, writeAccounts, maskCredential } from "./store";
     5→import { getExchange } from "./exchanges";
     6→import type {
     7→  ExchangeId,
     8→  CredentialField,
     9→  Account,
    10→  AccountRecord,
    11→  CreateAccountResult,
    12→  UpdateAccountResult,
    13→  ListAccountsResult,
    14→  ViewAccountResult,
    15→  RemoveAccountResult,
    16→} from "./types";
    17→
    18→const MAX_NAME_LENGTH = 64;
    19→const MAX_CREDENTIAL_LENGTH = 256;
    20→
    21→function validateCredential(value: string, field: string): string | null {
    22→  const trimmed = value.trim();
    23→  if (!trimmed) return `${field} cannot be empty`;
    24→  if (trimmed.length > MAX_CREDENTIAL_LENGTH) return `${field} exceeds max length (${MAX_CREDENTIAL_LENGTH})`;
    25→  return null;
    26→}
    27→
    28→function validateName(name: string): string | null {
    29→  const trimmed = name.trim();
    30→  if (!trimmed) return "name cannot be empty";
    31→  if (trimmed.length > MAX_NAME_LENGTH) return `name exceeds max length (${MAX_NAME_LENGTH})`;
    32→  return null;
    33→}
    34→
    35→function toAccount(record: AccountRecord): Account {
    36→  return {
    37→    id: record.id,
    38→    exchange: record.exchange,
    39→    name: record.name,
    40→    created_at: record.created_at,
    41→    updated_at: record.updated_at,
    42→  };
    43→}
    44→
    45→export async function findAccount(idOrName: string): Promise<AccountRecord | null> {
    46→  const accounts = await readAccounts();
    47→  // 1. Match by ID
    48→  const byId = accounts.find((a) => a.id === idOrName);
    49→  if (byId) return byId;
    50→  // 2. Match by name (exact, case-sensitive)
    51→  const byName = accounts.filter((a) => a.name === idOrName);
    52→  if (byName.length === 1) return byName[0];
    53→  if (byName.length > 1) return null; // ambiguous
    54→  return null;
    55→}
    56→
    57→export async function listAccounts(): Promise<ListAccountsResult> {
    58→  const accounts = await readAccounts();
    59→  return { success: true, accounts: accounts.map(toAccount) };
    60→}
    61→
    62→export async function addAccount(input: {
    63→  exchange: ExchangeId;
    64→  name: string;
    65→  api_key: string;
    66→  secret: string;
    67→  passphrase?: string;
    68→}): Promise<CreateAccountResult> {
    69→  // Validate
    70→  const nameErr = validateName(input.name);
    71→  if (nameErr) return { success: false, error: nameErr };
    72→
    73→  const keyErr = validateCredential(input.api_key, "api_key");
    74→  if (keyErr) return { success: false, error: keyErr };
    75→
    76→  const secretErr = validateCredential(input.secret, "secret");
    77→  if (secretErr) return { success: false, error: secretErr };
    78→
    79→  const exchange = getExchange(input.exchange);
    80→  if (exchange.fields.includes("passphrase")) {
    81→    if (!input.passphrase) return { success: false, error: "passphrase is required for " + exchange.name };
    82→    const ppErr = validateCredential(input.passphrase, "passphrase");
    83→    if (ppErr) return { success: false, error: ppErr };
    84→  }
    85→
    86→  const now = new Date().toISOString();
    87→  const record: AccountRecord = {
    88→    id: nanoid(12),
    89→    exchange: input.exchange,
    90→    name: input.name.trim(),
    91→    api_key: input.api_key.trim(),
    92→    secret: input.secret.trim(),
    93→    passphrase: input.passphrase?.trim(),
    94→    created_at: now,
    95→    updated_at: now,
    96→  };
    97→
    98→  const accounts = await readAccounts();
    99→  accounts.push(record);
   100→  await writeAccounts(accounts);
   101→
   102→  return { success: true, account: toAccount(record) };
   103→}
   104→
   105→export async function viewAccount(idOrName: string): Promise<ViewAccountResult> {
   106→  const record = await findAccount(idOrName);
   107→  if (!record) {
   108→    // Check if ambiguous name
   109→    const accounts = await readAccounts();
   110→    const byName = accounts.filter((a) => a.name === idOrName);
   111→    if (byName.length > 1) {
   112→      return { success: false, error: `Multiple accounts match name "${idOrName}". Use account ID instead.` };
   113→    }
   114→    return { success: false, error: `Account not found: ${idOrName}` };
   115→  }
   116→
   117→  const exchange = getExchange(record.exchange);
   118→  const masked: Partial<Record<CredentialField, string>> = {};
   119→  for (const field of exchange.fields) {
   120→    const value = record[field as keyof AccountRecord] as string | undefined;
   121→    if (value) masked[field] = maskCredential(value);
   122→  }
   123→
   124→  return { success: true, account: toAccount(record), masked_credentials: masked };
   125→}
   126→
   127→export async function updateAccount(idOrName: string, input: {
   128→  name?: string;
   129→  api_key?: string;
   130→  secret?: string;
   131→  passphrase?: string;
   132→}): Promise<UpdateAccountResult> {
   133→  const accounts = await readAccounts();
   134→  // Check for ambiguous name match
   135→  const byName = accounts.filter((a) => a.name === idOrName);
   136→  if (byName.length > 1) {
   137→    return { success: false, error: `Multiple accounts match name "${idOrName}". Use account ID instead.` };
   138→  }
   139→  const idx = accounts.findIndex((a) => a.id === idOrName || a.name === idOrName);
   140→  if (idx === -1) return { success: false, error: `Account not found: ${idOrName}` };
   141→
   142→  const record = accounts[idx];
   143→
   144→  if (input.name) {
   145→    const nameErr = validateName(input.name);
   146→    if (nameErr) return { success: false, error: nameErr };
   147→    record.name = input.name.trim();
   148→  }
   149→  if (input.api_key) {
   150→    const err = validateCredential(input.api_key, "api_key");
   151→    if (err) return { success: false, error: err };
   152→    record.api_key = input.api_key.trim();
   153→  }
   154→  if (input.secret) {
   155→    const err = validateCredential(input.secret, "secret");
   156→    if (err) return { success: false, error: err };
   157→    record.secret = input.secret.trim();
   158→  }
   159→  if (input.passphrase !== undefined) {
   160→    if (input.passphrase) {
   161→      const err = validateCredential(input.passphrase, "passphrase");
   162→      if (err) return { success: false, error: err };
   163→      record.passphrase = input.passphrase.trim();
   164→    } else {
   165→      record.passphrase = undefined;
   166→    }
   167→  }
   168→
   169→  record.updated_at = new Date().toISOString();
   170→  accounts[idx] = record;
   171→  await writeAccounts(accounts);
   172→
   173→  return { success: true, account: toAccount(record) };
   174→}
   175→
   176→export async function removeAccount(idOrName: string): Promise<RemoveAccountResult> {
   177→  const accounts = await readAccounts();
   178→  const byName = accounts.filter((a) => a.name === idOrName);
   179→  if (byName.length > 1) {
   180→    return { success: false, error: `Multiple accounts match name "${idOrName}". Use account ID instead.` };
   181→  }
   182→  const idx = accounts.findIndex((a) => a.id === idOrName || a.name === idOrName);
   183→  if (idx === -1) return { success: false, error: `Account not found: ${idOrName}` };
   184→
   185→  accounts.splice(idx, 1);
   186→  await writeAccounts(accounts);
   187→
   188→  return { success: true };
   189→}
